<script setup lang="ts">
import {computed,nextTick,onMounted,ref} from 'vue'
import {onBeforeRouteLeave} from 'vue-router'
import {GitBranch,Plus,Save,Upload,Undo2,Redo2,Play,Check,ArrowUpRight} from 'lucide-vue-next'
import WorkflowCanvas from '../components/WorkflowCanvas.vue'
import {api,type ReplayStatus} from '../services/api'
import {workflowsApi,type FlowGraph,type FlowNode,type NodeType,type WorkflowDraft,type WorkflowSummary,type WorkflowVersion,type WorkflowCheck,type WorkflowDebug} from '../services/workflows'
import {clone,customTemplate,makeNode,ports,presetNames,specs,template,traceValue} from '../utils/workflowGraph'
import {requestId} from '../utils/requestId'
const graph=ref<FlowGraph>(template()),selected=ref(''),name=ref('我的突破策略'),description=ref('')
const canvas=ref<InstanceType<typeof WorkflowCanvas>>(),draft=ref<WorkflowDraft|null>(null),items=ref<WorkflowSummary[]>([])
const busy=ref(false),error=ref(''),notice=ref(''),listError=ref(''),checked=ref<WorkflowCheck|null>(null),debug=ref<WorkflowDebug|null>(null)
const history=ref<ReplayStatus|null>(null),historyError=ref(''),symbol=ref(''),asOfDate=ref(''),direction=ref(0)
const selectedTemplate=ref('MOMENTUM_BREAKOUT'),versionId=ref(''),published=ref<WorkflowVersion[]>([])
const snapshot=()=>JSON.stringify({name:name.value.trim(),description:description.value.trim(),definition:graph.value})
const baseline=ref(snapshot()),dirty=computed(()=>snapshot()!==baseline.value)
const undo=ref<FlowGraph[]>([]),redo=ref<FlowGraph[]>([])
let createCommand=requestId(),publishCommand:{revision:number;id:string}|null=null
const node=computed(()=>graph.value.nodes.find(n=>n.id===selected.value))
const versions=computed(()=>draft.value?.versions??published.value)
const version=computed(()=>versions.value.find(v=>v.id===versionId.value))
const trace=computed(()=>debug.value?.nodeTrace??[])
const today=new Date().toLocaleDateString('en-CA',{timeZone:'Asia/Shanghai'})
function invalidate(){checked.value=null;debug.value=null;notice.value=''}
function change(value:FlowGraph){if(busy.value)return;undo.value.push(clone(graph.value));if(undo.value.length>50)undo.value.shift();redo.value=[];graph.value=clone(value);invalidate()}
function travel(back:boolean){if(busy.value)return;const from=back?undo:redo,to=back?redo:undo,value=from.value.pop();if(!value)return;to.value.push(clone(graph.value));graph.value=value;selected.value='';invalidate()}
function updateNode(key:string,value:string|number){if(!node.value)return;const next=clone(graph.value),target=next.nodes.find(n=>n.id===node.value!.id)!;if(key==='label')target.label=String(value);else target.params[key]=value
 next.edges=next.edges.filter(e=>{const a=next.nodes.find(n=>n.id===e.source),b=next.nodes.find(n=>n.id===e.target);return a&&b&&ports(a).outputs[e.sourcePort]===ports(b).inputs[e.targetPort]&&ports(a).outputs[e.sourcePort]})
 change(next)}
function add(type:NodeType){if(busy.value)return;if(graph.value.nodes.length>=40){error.value='最多40个节点';return}const node=makeNode(type,150+graph.value.nodes.length*30,170+graph.value.nodes.length*20);change({...graph.value,nodes:[...graph.value.nodes,node]});selected.value=node.id}
function dragPalette(e:DragEvent,type:string){e.dataTransfer?.setData('application/x-strategy-node',type)}
function reset(){if(busy.value)return;if(dirty.value&&!window.confirm('当前草稿尚未保存。是否放弃本地修改并新建？'))return;draft.value=null;graph.value=selectedTemplate.value==='CUSTOM'?customTemplate():template(selectedTemplate.value);name.value=selectedTemplate.value==='CUSTOM'?'收盘价高于均线':(presetNames[selectedTemplate.value]??'新策略')+'工作流';description.value='';selected.value='';undo.value=[];redo.value=[];versionId.value='';published.value=[];createCommand=requestId();publishCommand=null;baseline.value='';invalidate();nextTick(()=>canvas.value?.fit())}
async function refresh(){try{items.value=await workflowsApi.list();listError.value=''}catch(e){listError.value=e instanceof Error?e.message:'草稿列表暂不可用'}}
function accept(value:WorkflowDraft){draft.value=value;graph.value=clone(value.definition);name.value=value.name;description.value=value.description;baseline.value=snapshot()}
async function open(id:string){if(busy.value||draft.value?.id===id)return;if(dirty.value&&!window.confirm('是否放弃本地未保存修改并打开此草稿？'))return;busy.value=true;error.value='';try{accept(await workflowsApi.draft(id));selected.value='';versionId.value=draft.value?.versions[0]?.id??'';undo.value=[];redo.value=[];invalidate();await nextTick();canvas.value?.fit()}catch(e){fail(e)}finally{busy.value=false}}
function fail(e:unknown){error.value=e instanceof Error?e.message:'操作失败，请重试'}
async function saveCore(){if(!name.value.trim())throw new Error('请填写策略名称');if(!dirty.value&&draft.value)return draft.value
 const value={name:name.value.trim(),description:description.value.trim(),definition:clone(graph.value)}
 const result=draft.value?await workflowsApi.save(draft.value.id,{...value,expectedRevision:draft.value.revision}):await workflowsApi.create({...value,clientRequestId:createCommand})
 accept(result);return result}
async function save(){busy.value=true;error.value='';try{await saveCore();notice.value='草稿已保存';await refresh()}catch(e){fail(e)}finally{busy.value=false}}
async function validate(){busy.value=true;error.value='';notice.value='';try{checked.value=await workflowsApi.validate(clone(graph.value));notice.value='校验通过，可发布并运行'}catch(e){fail(e)}finally{busy.value=false}}
async function publish(){busy.value=true;error.value='';notice.value='';try{
 checked.value=await workflowsApi.validate(clone(graph.value));const saved=await saveCore()
 if(publishCommand?.revision!==saved.revision)publishCommand={revision:saved.revision,id:requestId()}
 const value=await workflowsApi.publish(saved.id,saved.revision,publishCommand.id)
 if(!saved.versions.some(v=>v.id===value.id))saved.versions.push(value);versionId.value=value.id
 notice.value='已发布 v'+value.version+'，可用于回测和历史 / 实时模拟';await refresh()
 }catch(e){fail(e)}finally{busy.value=false}}
function selectSymbol(){const row=history.value?.symbols.find(s=>s.symbol===symbol.value);asOfDate.value=row?.endDate.slice(0,10)??today}
async function runDebug(){if(!symbol.value||!asOfDate.value){error.value='请选择有真实数据的品种与观测日期';return}busy.value=true;error.value='';debug.value=null;try{const end=new Date(asOfDate.value+'T23:59:59+08:00').getTime();if(!Number.isFinite(end))throw new Error('日期格式无效');debug.value=await workflowsApi.debug(clone(graph.value),symbol.value,new Date(Math.min(Date.now(),end)).toISOString(),direction.value)}catch(e){fail(e)}finally{busy.value=false}}
onBeforeRouteLeave(()=>!dirty.value||window.confirm('本地修改尚未保存，是否离开？'))
onMounted(async()=>{await Promise.allSettled([refresh(),api.replayStatus().then(v=>{history.value=v;symbol.value=v.symbols[0]?.symbol??'';selectSymbol()}).catch(()=>historyError.value='真实回放目录暂不可用，试算需要已有日线数据')]);await nextTick();canvas.value?.fit()})
</script>
<template>
 <div class="workflow-page">
  <header class="workflow-heading"><div><span class="eyebrow"><GitBranch :size="14"/> STRATEGY WORKFLOW</span><h2>让交易规则，成为可执行的流程。</h2><p>从行情到条件，再到风控与动作。拖动节点连接你的思路，在真实历史中逐步验证。</p></div><RouterLink to="/strategy">返回研究工具 <ArrowUpRight :size="14"/></RouterLink></header>
  <div class="workflow-toolbar"><div class="template-picker"><select aria-label="打开已存工作流" :disabled="busy" :value="draft?.id??''" @change="open(($event.target as HTMLSelectElement).value)"><option value="" disabled>打开已存草稿</option><option v-for="item in items" :key="item.id" :value="item.id">{{item.name}} · r{{item.revision}}</option></select><select v-model="selectedTemplate" aria-label="工作流模板" :disabled="busy"><option v-for="(label,key) in presetNames" :key="key" :value="key">{{label}}模板</option><option value="CUSTOM">自定义：收盘价高于均线</option></select><button :disabled="busy" @click="reset"><Plus :size="15"/>新建</button></div><div class="actions"><span class="save-status">{{dirty?'有未保存修改':draft?'草稿 r'+draft.revision:'本地模板'}}</span><button :disabled="busy||!undo.length" aria-label="撤销" @click="travel(true)"><Undo2 :size="15"/></button><button :disabled="busy||!redo.length" aria-label="重做" @click="travel(false)"><Redo2 :size="15"/></button><button :disabled="busy" @click="validate"><Check :size="15"/>校验</button><button :disabled="busy" @click="save"><Save :size="15"/>保存草稿</button><button class="primary" :disabled="busy" @click="publish"><Upload :size="15"/>{{busy?'处理中…':'发布版本'}}</button></div></div>
  <p v-if="error" role="alert" class="flow-error">{{error}}</p><p v-if="notice" role="status" class="flow-success">{{notice}}</p>
  <div class="workflow-layout">
   <aside class="node-library"><h3>节点库 <small>{{graph.nodes.length}} / 40</small></h3><p>拖入画布，或点击添加</p><button v-for="(spec,type) in specs" :key="type" :draggable="!busy" :disabled="busy" :title="spec.hint" @dragstart="dragPalette($event,type)" @click="add(type)"><i :style="{background:spec.color}"/><span>{{spec.name}}<small>{{spec.hint}}</small></span><Plus :size="13"/></button><div class="saved-drafts"><h3>已存草稿</h3><p v-if="listError" role="alert">{{listError}} <button @click="refresh">重试</button></p><p v-else-if="!items.length">保存后可在这里继续编辑。</p><button v-for="item in items" :key="item.id" :disabled="busy" :class="{active:draft?.id===item.id}" @click="open(item.id)">{{item.name}}<small>r{{item.revision}} · {{item.publishedVersion?'已发布 v'+item.publishedVersion:'未发布'}}</small></button></div></aside>
   <main class="canvas-column"><WorkflowCanvas ref="canvas" :model-value="graph" v-model:selected="selected" :trace="trace" :disabled="busy" @update:model-value="change" @error="error=$event"/><div class="canvas-legend"><span><i class="series"/>日线 / 数值</span><span><i class="boolean"/>条件</span><span><i class="risk"/>风控</span><span>点击连线可删除 · Delete 删除选中 · Ctrl + 滚轮缩放</span></div></main>
   <aside class="workflow-inspector">
    <fieldset :disabled="busy"><legend>策略信息</legend><label>名称<input v-model="name" maxlength="120" aria-label="工作流名称"/></label><label>说明<textarea v-model="description" maxlength="1000" rows="2" aria-label="工作流说明"/></label></fieldset>
    <fieldset v-if="node" :disabled="busy"><legend>{{specs[node.type].name}}</legend><p>{{specs[node.type].hint}}</p><label>节点名称<input :value="node.label" maxlength="80" @change="updateNode('label',($event.target as HTMLInputElement).value)"/></label><label v-for="param in specs[node.type].params" :key="param.key">{{param.label}}<select v-if="param.options" :value="node.params[param.key]" @change="updateNode(param.key,($event.target as HTMLSelectElement).value)"><option v-for="(label,key) in param.options" :key="key" :value="key">{{label}}</option></select><input v-else type="number" :value="node.params[param.key]" :min="param.min" :max="param.max" :step="param.step" @change="updateNode(param.key,Number(($event.target as HTMLInputElement).value))"/></label><button class="danger" @click="canvas?.remove()">删除节点与相关连线</button></fieldset>
    <div v-else class="inspector-empty"><GitBranch :size="24"/><p>选择一个节点<br/>配置参数与交易条件</p></div>
    <div v-if="checked" class="check-info">已校验 {{checked.nodeCount}} 个节点<br/>指标预热 {{checked.requiredBars}} 根日线<br/>固定 {{checked.risk.lots}} 手 · 保护 {{checked.risk.stopLossAtr}} / {{checked.risk.takeProfitAtr}} ATR</div>
   </aside>
  </div>
  <section class="flow-runner"><div><span class="eyebrow">OBSERVE → VERIFY</span><h3>按历史时点试算</h3><p>仅计算信号，不提交委托。只读取观测日期前已完成的真实日线；节点显示候选不代表已经成交。</p></div><div class="debug-controls"><label>品种<select v-model="symbol" :disabled="busy" @change="selectSymbol"><option v-for="row in history?.symbols??[]" :key="row.symbol" :value="row.symbol">{{row.symbol}} · {{row.startDate.slice(0,10)}} 至 {{row.endDate.slice(0,10)}}</option></select></label><label>观测日期<input v-model="asOfDate" type="date" :max="today" :disabled="busy"/></label><label>假设持仓<select v-model.number="direction" :disabled="busy"><option :value="0">空仓</option><option :value="1">持有多头</option><option :value="-1">持有空头</option></select></label><button :disabled="busy||!symbol" @click="runDebug"><Play :size="14"/>试算节点</button></div><p v-if="historyError" class="flow-error">{{historyError}}</p><div v-if="debug" class="debug-result"><strong>{{debug.signal}} · {{debug.reason}}</strong><p>{{debug.source}} · 已知 {{debug.historyCount}} 根 · 信号时间 {{debug.signalTime??'暂无'}}。{{debug.message}}</p><div class="trace-table"><table><thead><tr><th>节点</th><th>状态</th><th>计算值</th><th>原因</th></tr></thead><tbody><tr v-for="row in trace" :key="row.nodeId" @click="selected=row.nodeId"><td>{{row.label}}</td><td>{{row.status}}</td><td>{{traceValue(row.value)}}</td><td>{{row.reason}}</td></tr></tbody></table></div></div></section>
  <section class="flow-versions"><div><span class="eyebrow">PUBLISH → EXPERIMENT</span><h3>运行已发布版本</h3><p>发布时固定完整规则与风控；之后编辑草稿，不会改变已创建的试验。</p></div><div v-if="versions.length" class="version-actions"><select v-model="versionId" aria-label="发布版本" :disabled="busy"><option value="">选择版本</option><option v-for="v in versions" :key="v.id" :value="v.id">{{v.name}} · v{{v.version}} · {{v.lots}} 手</option></select><template v-if="version"><RouterLink :to="{path:'/backtest',query:{workflowVersion:version.id,symbol:symbol||undefined}}">历史回测 ↗</RouterLink><RouterLink :to="{path:'/paper',query:{workflowVersion:version.id,symbol:symbol||undefined}}">历史 / 实时模拟 ↗</RouterLink></template></div><p v-else class="empty-version">校验并发布后，即可创建版本固定的策略试验。</p></section>
  <p class="workflow-scope">当前支持日线规则、固定手数和入场 ATR 保护。回测在下一根日线成交；模拟交易按真实行情、保证金和成交量约束撮合，两者成交模型存在差异。实时策略监测需保持模拟交易页面打开并启动。</p>
 </div>
</template>
<style scoped>
.workflow-page{min-width:0}.workflow-heading{display:flex;justify-content:space-between;align-items:center;gap:1rem;margin:.8rem 0 1.6rem}.eyebrow{display:flex;align-items:center;gap:.5rem;font-size:.62rem;letter-spacing:.12em;color:var(--color-accent)}.workflow-heading h2{font:500 clamp(1.3rem,2.1vw,2rem) var(--font-display);margin:.75rem 0}.workflow-heading p,.flow-runner p,.flow-versions p{font-size:.74rem;line-height:1.9;color:var(--color-ink-secondary);margin:.4rem 0}.workflow-heading a{font-size:.7rem;color:var(--color-accent);display:flex;gap:.4rem;white-space:nowrap}.workflow-toolbar,.actions,.template-picker{display:flex;align-items:center;gap:.5rem}.workflow-toolbar{justify-content:space-between;flex-wrap:wrap;margin-bottom:.9rem}.workflow-page button,.workflow-page select,.workflow-page input,.workflow-page textarea{font:inherit}.workflow-page button{display:inline-flex;align-items:center;justify-content:center;white-space:nowrap;gap:.4rem;border:1px solid var(--color-line);background:var(--color-surface-raised);color:var(--color-ink);padding:.6rem .75rem;border-radius:.4rem;cursor:pointer;font-size:.7rem}.workflow-page button:disabled{opacity:.45;cursor:default}.workflow-page button.primary{background:var(--color-accent);border-color:var(--color-accent);color:white}.workflow-page select,.workflow-page input,.workflow-page textarea{width:100%;box-sizing:border-box;min-width:0;border:1px solid var(--color-line);background:var(--color-surface-raised);color:var(--color-ink);padding:.6rem;border-radius:.4rem;font-size:.72rem}.save-status{font-size:.64rem;color:var(--color-ink-tertiary);margin-right:.5rem}.template-picker{flex-wrap:wrap}.template-picker select{width:auto;max-width:220px;min-width:110px;flex:1}.workflow-layout{display:grid;grid-template-columns:190px minmax(0,1fr) 218px;gap:.8rem;align-items:start}.node-library,.workflow-inspector{border:1px solid var(--color-line);border-radius:.65rem;background:var(--color-surface-raised);padding:.9rem;min-width:0}.node-library h3{font-size:.76rem;margin:0 0 .4rem;display:flex;justify-content:space-between}.node-library h3 small{font-size:.6rem;color:var(--color-ink-tertiary);font-weight:400}.node-library p{font-size:.63rem;color:var(--color-ink-tertiary);line-height:1.7}.node-library>button{display:flex;width:100%;justify-content:start;gap:.5rem;border:0;padding:.65rem .1rem;border-radius:0;background:transparent;border-bottom:1px solid var(--color-line);text-align:left}.node-library i{width:7px;height:7px;border-radius:50%;flex-shrink:0}.node-library button span{flex:1;font-size:.7rem}.node-library button small{display:block;font-size:.57rem;line-height:1.6;color:var(--color-ink-tertiary);margin-top:.2rem}.saved-drafts{margin-top:1.5rem}.saved-drafts button{display:block;width:100%;text-align:left;margin-top:.4rem}.saved-drafts .active{border-color:var(--color-accent)}.canvas-column{min-width:0}.canvas-legend{display:flex;gap:.8rem;flex-wrap:wrap;font-size:.58rem;color:var(--color-ink-tertiary);padding:.7rem .2rem}.canvas-legend span{display:flex;gap:.3rem;align-items:center}.canvas-legend i{width:6px;height:6px;border-radius:50%}.series{background:#5e8fa0}.boolean{background:#b78b49}.risk{background:#ac725b}.workflow-inspector fieldset{padding:0;margin:0 0 1.3rem;border:0;min-width:0}.workflow-inspector legend{font-size:.75rem;font-weight:600;margin-bottom:.6rem}.workflow-inspector label{display:grid;gap:.4rem;margin:.65rem 0;font-size:.65rem;color:var(--color-ink-secondary)}.workflow-inspector p{font-size:.65rem;line-height:1.8;color:var(--color-ink-tertiary)}.workflow-page .danger{color:#b45a50;font-size:.62rem;width:100%;margin-top:.6rem}.inspector-empty{display:grid;place-items:center;text-align:center;padding:1.8rem .2rem;color:var(--color-ink-tertiary)}.check-info{padding:.8rem;background:var(--color-accent-soft);font-size:.65rem;line-height:2;color:var(--color-accent);border-radius:.4rem}.flow-error,.flow-success{font-size:.73rem;line-height:1.8;border-radius:.4rem;padding:.7rem .9rem}.flow-error{background:var(--color-warning-soft);color:var(--color-warning)}.flow-success{background:var(--color-accent-soft);color:var(--color-accent)}.flow-runner,.flow-versions{border-top:1px solid var(--color-line);padding:1.5rem 0;margin-top:1rem}.flow-runner h3,.flow-versions h3{font-size:1rem;margin:.65rem 0}.debug-controls{display:flex;gap:.7rem;align-items:end;flex-wrap:wrap;margin-top:1rem}.debug-controls label{display:grid;gap:.4rem;font-size:.65rem;color:var(--color-ink-secondary)}.debug-controls label:first-child{flex:1;min-width:200px}.debug-result{margin-top:1rem;padding:1rem;border:1px solid var(--color-line);border-radius:.6rem;font-size:.76rem}.trace-table{overflow:auto;margin-top:1rem}table{width:100%;border-collapse:collapse;text-align:left;font-size:.66rem}th,td{padding:.65rem .7rem;border-bottom:1px solid var(--color-line);vertical-align:top}th{color:var(--color-ink-tertiary);white-space:nowrap}td:nth-child(3){font-family:var(--font-numeric);max-width:260px;overflow-wrap:anywhere}tbody tr{cursor:pointer}tbody tr:hover{background:var(--color-accent-soft)}.version-actions{display:flex;gap:1rem;align-items:center;flex-wrap:wrap;margin-top:.8rem}.version-actions select{max-width:380px}.version-actions a{color:var(--color-accent);font-size:.75rem}.empty-version{padding:.7rem 0}.workflow-scope{font-size:.65rem;line-height:1.9;color:var(--color-ink-tertiary);max-width:75rem}.actions{flex-wrap:wrap}@media(max-width:1400px){.workflow-layout{grid-template-columns:155px minmax(0,1fr)}.workflow-inspector{grid-column:1/-1;display:grid;grid-template-columns:1fr 1fr;gap:1rem}.workflow-inspector fieldset{margin:0}.node-library{padding:.7rem}}@media(max-width:750px){.workflow-heading{display:block}.workflow-heading a{margin-top:1rem}.workflow-layout{grid-template-columns:minmax(0,1fr)}.node-library{display:flex;gap:.5rem;overflow:auto}.node-library>h3,.node-library>p,.saved-drafts{display:none}.node-library>button{flex-shrink:0;width:115px;border:1px solid var(--color-line);padding:.5rem}.node-library button small{display:none}.workflow-inspector{grid-template-columns:1fr}.save-status{display:none}.actions button{font-size:.63rem}.template-picker{width:100%}.workflow-toolbar{gap:.7rem}}
</style>
